@spec sample_page_spec  src=tests/specs/sample_page_spec.lua  loc=94  cases=5
@exercises commandManager (h.cmgr)
@surface   cmgr:installManifest, cmgr:scope
@harness   mk

# Intent
  Pin-tests for samplePage's Page interface (bind / unbind / focusState).
  Render methods pull in ImGui and are exercised manually in REAPER.
  
  samplePage requires ImGui at module scope; stub via package.preload
  before the first require so the module loads in the pure-Lua harness.

# Helpers
  @fn newSamplePage(cm, cmgr, chrome, gui)  @ 20-23

# Cases
  @case 'the manifest declares every command the sample page registers'  [harness]  @ 30-47
  @case 'setTrack(track) re-keys cm to that track via the page's own sv'  [harness]  @ 51-59
  @case 'setTrack(nil) does not re-key cm'  [harness]  @ 62-70
  @case 'focusState before any render returns both bits false'  [harness]  @ 73-80
  @case 'bind re-keys cm to the page track on every activation, not just the first'  [harness]  @ 83-92

# Uses (outbound edges)
  @use call cmgr:installManifest  @ 37
  @use call cmgr:scope  @ 39

